import type { FlowArrayType, FlowObjectType, FlowSchemaType, FlowValueType } from '../FlowTypes';
import type { FlowVariableDefinition } from '../FlowVariables';
export type SchemaArrayElementType<T> = T extends {
    elementType: infer E;
} ? E extends FlowObjectType<infer F> ? FlowSchemaType<F> : E extends Typed<infer R> ? R : unknown : never;
export declare function AppendToFlowVariables<T extends FlowVariableDefinition, S extends Record<string, FlowValueType>, KV extends {
    [K in keyof S]?: S[K] extends FlowArrayType ? SchemaArrayElementType<S[K]> | SchemaArrayElementType<S[K]>[] | string : never;
}>(_definition: T, _variables: FlowSchemaType<S>, _values: KV): {
    type: 'appendflowvariables';
};
